#include <stdint.h>

int bit_window(uint32_t value, unsigned shift, uint32_t *out) {
    @CONTEXT@
    @CANDIDATE@
    *out = value << shift;
    return 0;
}

export function slotValue(items, index) {
    @CONTEXT@
    @CANDIDATE@
    return items[index];
}

#include <string.h>

void erase_snapshot(unsigned char seed, unsigned char snapshot[4]) {
    unsigned char secret[4] = {seed, seed, seed, seed};
    unsigned char buffer[4] = {7, 7, 7, 7};
    @CONTEXT@
    @CANDIDATE@
    memcpy(snapshot, secret, sizeof secret);
    (void)buffer;
}
